/**
 * Curated Adani catalogue: what the group buys most (ranked from FY25-26 PO lines per ProcMart product type),
 * listed as proper products — real brands, real dimensions and ratings, a full spec sheet keyed to the ProcMart
 * attribute template of the product type, a buyer-readable description and the SAP short text people search with.
 *
 * ILLUSTRATIVE COMMERCIALS: prices, distributors and SAP material codes are made up for the showcase.
 * Part numbers follow the manufacturers' published designation systems.
 */
export interface CItem {
  key: string; name: string; brand: string; mpn: string; uom: string;
  category: string; product: string;            // ProcMart category + product type name (resolved against taxonomy.json)
  description: string; specs: Record<string, string>; price: number;   // INR, excl. GST, per uom
  art: { kind: string; color: string; label: string; o?: Record<string, any> };
  equiv?: string;                                // items sharing this key are interchangeable (approved alternatives)
  sap: string;                                   // SAP-style short text, searchable
}

const out: CItem[] = [];
const seen = new Set<string>();
const slug = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
function add(i: Omit<CItem, 'key' | 'specs'> & { specs: Record<string, string | number | undefined | null> }) {
  let key = slug(`${i.brand}-${i.mpn}`); while (seen.has(key)) key += '-x'; seen.add(key);
  const specs: Record<string, string> = {};
  for (const [k, v] of Object.entries(i.specs)) if (v !== undefined && v !== null && v !== '') specs[k] = String(v);
  out.push({ ...i, key, specs, price: Math.round(i.price * 100) / 100 });
}
const r = (n: number, step = 5) => Math.max(step, Math.round(n / step) * step);
