// Align spec names with each product type's own attribute template (taxonomy.json names differ per type).
const RENAME: Record<string, Record<string, string>> = {
  'POWER CONTACTOR': { 'CURRENT RATING': 'RATED OPERATIONAL CURRENT', 'NUMBER OF POLES': 'NO OF POLES', 'SWITCHING VOLTAGE': 'MAX OPERATIONAL VOLTAGE' },
  'OVERLOAD RELAY': { 'NO OF POLES': 'NUMBER OF POLES', 'VOLTAGE RATING': 'SWITCHING VOLTAGE' },
  'RING LUG': { 'CONDUCTOR SIZE': 'CABLE GAUGE', MATERIAL: 'LUG MATERIAL' },
  'INDUSTRIAL SOCKET': { 'VOLTAGE RATING': 'VOLTAGE', 'NO OF PINS': 'POLE' },
  'TYRE COUPLING': { 'COUPLING TYPE': 'TYPE', MATERIAL: 'HUB MATERIAL' },
  'JAW COUPLING': { 'COUPLING TYPE': 'CONNECTION TYPE' },
  'NITRILE GLOVES': { Coating: 'MATERIAL' }, 'CUT RESISTANT GLOVES': {}, 'HEX NUT': { SIZE: 'DIAMETER', 'THREAD TYPE': 'THREAD DESIGNATION' },
  'SOCKET HEAD CAP SCREW': { 'THREAD SIZE': 'THREAD TYPE', 'DRIVE TYPE': 'TYPE', 'MODEL NO': 'PART CODE' },
  'SOCKET SET': { 'SOCKET TYPE': 'TYPE OF SOCKET' }, 'ALLEN KEY SET': { 'NUMBER OF PIECES': 'NUMBER OF KEYS' },
  'AIR CYLINDER': { STANDARD: 'CYLINDER TYPE' }, 'SPIRAL WOUND GASKET': { 'NOMINAL SIZE': 'NOMINAL BORE SIZE', 'PRESSURE CLASS': 'PRESSURE RATING', MATERIAL: 'WINDING MATERIAL', 'OUTER RING': 'ADDITIONAL INFORMATION' },
  'CENTRIFUGAL PUMP': { HEAD: 'RATED HEAD', MATERIAL: 'HOUSING MATERIAL' }, 'MULTIMETER': { 'MEASUREMENT TYPE': 'MULTIMETER TYPE' },
  'CLAMP METER': { 'CURRENT RANGE': 'MAX CURRENT RANGE', 'JAW OPENING': 'JAW SIZE', 'SAFETY RATING': 'VOLTAGE RATING' },
  'DIGITAL CALIPER': { RESOLUTION: 'LEAST COUNT', 'DISPLAY TYPE': 'TYPE' }, CALIPER: { RESOLUTION: 'LEAST COUNT', 'DISPLAY TYPE': 'TYPE' },
  'DIAL CALIPER': { 'MEASURING RANGE': 'MEASUREMENT RANGE', RESOLUTION: 'LEAST COUNT', 'DISPLAY TYPE': 'TYPE' }, MICROMETER: { 'MEASURING RANGE': 'MEASUREMENT RANGE', RESOLUTION: 'LEAST COUNT' },
  'CHAIN PULLEY BLOCK': { 'LIFT HEIGHT': 'LIFTING HEIGHT', 'CHAIN TYPE': 'MATERIAL' },
  LAPTOP: { PROCESSOR: 'PROCESSOR TYPE', RAM: 'RAM CAPACITY', STORAGE: 'STORAGE CAPACITY' }, 'LED MONITOR': { RESOLUTION: 'DISPLAY RESOLUTION' },
  'KEYBOARD AND MOUSE': { TYPE: 'CONNECTION INTERFACE' }, 'LASER PRINTER': { TYPE: 'CONNECTION INTERFACE' }, CHANNEL: { SIZE: 'CHANNEL TYPE' },
  'STRETCH FILM': { WIDTH: 'FILM WIDTH', WEIGHT: 'FLIM LENGTH' }, 'COTTON MOP HEAD': { MATERIAL: 'HEAD TYPE' }, 'FLAT TOP GARBAGE BAG': { 'PACK SIZE': 'CAPACITY', 'MODEL NO': 'MATERIAL' },
  'OIL FILTER': {}, 'FUEL FILTER': {}, 'ENGINE AIR FILTER': {}, 'FILTER PAPER': { GRADE: 'GSM' },
};
for (const i of out) {
  const m = RENAME[i.product]; if (!m) continue;
  for (const [from, to] of Object.entries(m)) if (from in i.specs) { if (!(to in i.specs)) i.specs[to] = i.specs[from]; delete i.specs[from]; }
}
// required attributes that a family states in another form
for (const i of out) {
  const s = i.specs;
  if (i.product === 'TYRE COUPLING') s['COUPLING SIZE'] = i.mpn.split(' ')[1];
  if (i.product === 'SPIRAL WOUND GASKET') { s.DIAMETER = s['NOMINAL BORE SIZE']; s.MATERIAL = 'SS316 / flexible graphite'; s['FILLER MATERIAL'] = 'Flexible graphite'; }
  if (i.product === 'CPVC PIPE') s['WALL THICKNESS'] = `${(parseInt(s.DIAMETER.split('(')[1]) / 11).toFixed(1)} mm (SDR 11)`;
  if (i.product === 'CHANNEL') s.LENGTH = '6 / 12 m';
  if (i.product === 'COTTON MOP HEAD') s.COLOR = 'White';
}
// Extra specs outside a type's template (e.g. ACCURACY, IP RATING, NLGI GRADE) are kept: they show as additional specs.
export const CATALOGUE = out;
